package native
import("bytes";"testing")
func TestSourceStageOriginalQueries(t *testing.T){s,e:=New(42);if e!=nil{t.Fatal(e)};defer s.Close();if _,e=s.CommandRaw([]byte(`{"op":"source-stage-component","id":1,"legacyFlags":100001,"kind":"button","x":2,"y":3,"width":10,"height":3}`));e!=nil{t.Fatal(e)};before,_:=s.Snapshot();v,e:=s.SourceStageTween(-200,1000,210,420,1);if e!=nil||v!=400{t.Fatal(v,e)};v,e=s.SourceStageInkOpacity(420,420,768,1536,760);if e!=nil||v!=880{t.Fatal(v,e)};h,e:=s.SourceStageHit(3,4);if e!=nil||h==nil||h.ID!=100001||h.Item!=0{t.Fatal(h,e)};h.ID=0;again,_:=s.SourceStageHit(3,4);if again.ID!=100001{t.Fatal("borrowed")};h,e=s.SourceStageHit(-1,-1);if e!=nil||h!=nil{t.Fatal(h,e)};if _,e=s.SourceStageTween(0,100,5,10,4);e==nil{t.Fatal("easing")};if _,e=s.SourceStageInkOpacity(0,0,0,-1,0);e==nil{t.Fatal("band")};after,_:=s.Snapshot();if !bytes.Equal(before,after){t.Fatal("query mutated")}}
